def _verificar_origen(casos, esperadas, normas, proposito) -> dict:
    """Guardas previas a copiar cualquier entrada; devuelve qué se verificó.

    Las rutas se resuelven (incluidos symlinks) antes de comparar con ``practica/``. El
    chequeo del kit se corre sobre las rutas ORIGINALES: la copia en ``salida/entradas``
    nunca tiene esperadas al lado y por eso no lo dispararía.
    """
    if proposito not in PROPOSITOS:
        raise ValueError(f"propósito inválido; usar uno de {', '.join(PROPOSITOS)}")
    practica = _PRACTICA.resolve()
    en_practica = []
    for nombre, ruta in (("casos", casos), ("esperadas", esperadas)):
        resuelta = Path(ruta).resolve()
        if resuelta == practica or practica in resuelta.parents:
            en_practica.append(nombre)
    if proposito == "plomeria":
        # Solo plomería puede usar práctica; la copia aislada sigue revisada por `jugar`.
        return {"datos_practica": en_practica, "esperadas_al_alcance": "omitida_plomeria"}
    if en_practica:
        raise ValueError(
            f"{' y '.join(en_practica)} dentro de practica/: nunca se evalúan ni optimizan prompts "
            "con práctica; para probar solo la plomería usar --solo-plomeria")
    revisar_que_no_haya_esperadas(Path(normas), Path(casos))
    return {"datos_practica": [], "esperadas_al_alcance": "verificada_en_origen"}

@classmethod
def cargar(cls, configuracion: Configuracion):
    import torch

    if not torch.cuda.is_available():
        raise RuntimeError("El baseline requiere una GPU CUDA; no se carga en CPU")
    import transformers
    from .carga import cargar_solo_texto
    # Tokenizer, no AutoProcessor: el agente es solo texto, usa el mismo chat template que el
    # entrenamiento, y el procesador de Gemma 4 exige torchvision por su parte de video.
    procesador = transformers.AutoTokenizer.from_pretrained(
        configuracion.modelo, revision=configuracion.revision, padding_side="left")
    modelo = cargar_solo_texto(transformers, configuracion.modelo, configuracion.revision,
                               dtype=getattr(torch, configuracion.dtype),
                               device_map=configuracion.device_map)
    # Sin attn_implementation: transformers elige SDPA donde se soporta. Forzarlo rompía la torre
    # de audio de Gemma 4 (hoy ya no se carga, pero el default sigue siendo lo correcto).
    if configuracion.adapter_repo:
        modelo = cls._fusionar_adapter(modelo, configuracion)
    modelo.eval()
    return cls(modelo, procesador, configuracion)

@staticmethod
def _fusionar_adapter(modelo, configuracion: Configuracion):
    """Aplica el LoRA y lo fusiona en memoria: la inferencia no paga capas extra."""
    from peft import PeftConfig, PeftModel

    origen = {"revision": configuracion.adapter_revision,
              "subfolder": configuracion.adapter_subcarpeta or None}
    config = PeftConfig.from_pretrained(configuracion.adapter_repo, **origen)
    # `config.revision` es la revisión de la base con la que se entrenó el adapter.
    if (config.base_model_name_or_path, config.revision) != (configuracion.modelo, configuracion.revision):
        raise ValueError("El adapter fue entrenado sobre otra base o revisión")
    peft = PeftModel.from_pretrained(modelo, configuracion.adapter_repo, config=config, **origen)
    return peft.merge_and_unload()

def escribir_normas(base: Path, destino: Path, valores: dict[str, int]) -> Path:
    """Copia las secciones de `base` a `destino` (nueva) con `valores` aplicados a sus parámetros."""
    base, destino = Path(base), Path(destino)
    entradas = parametros_base(base)
    desconocidos = set(valores) - {p["codigo"] for p in entradas}
    if desconocidos:
        raise ValueError(f"parámetros inexistentes: {sorted(desconocidos)}")
    destino.mkdir(parents=True)
    for archivo in sorted(base.glob("NOR-*.md")):
        shutil.copyfile(archivo, destino / archivo.name)
    for entrada in entradas:
        if entrada["codigo"] in valores:
            valor = valores[entrada["codigo"]]
            if type(valor) is not int or valor < 0:
                raise ValueError("los valores de parámetros son enteros no negativos")
            entrada["valor"] = valor
    (destino / "parametros.yaml").write_text(
        yaml.safe_dump({"parametros": entradas}, allow_unicode=True, sort_keys=False), encoding="utf-8")
    cargar_parametros(destino)  # falla aquí si el archivo escrito no es legible por el kit
    return destino


class CarpetasNormas:
    """Una carpeta por conjunto de valores, creada una sola vez bajo `raiz`, con su buscador.

    `fabrica(ruta)` arma el buscador igual que la entrega (por ejemplo `entrega.construir_buscador`).
    """

    def __init__(self, base: Path, raiz: Path, fabrica):
        self.base, self.raiz, self.fabrica = Path(base), Path(raiz), fabrica
        self.originales = {p["codigo"]: p["valor"] for p in parametros_base(self.base)}
        self._carpetas: dict[tuple, tuple[Path, object]] = {}

    def completar(self, valores: dict[str, int]) -> dict[str, int]:
        """Valores originales con `valores` aplicados encima."""
        return {**self.originales, **valores}

    def obtener(self, valores: dict[str, int]):
        """(ruta, buscador) de la carpeta con esos valores sobre los originales."""
        completos = self.completar(valores)
        clave = tuple(sorted(completos.items()))
        if clave not in self._carpetas:
            ruta = escribir_normas(self.base, self.raiz / f"normas-{len(self._carpetas):05d}", completos)
            self._carpetas[clave] = (ruta, self.fabrica(ruta))
        return self._carpetas[clave]

@dataclass(frozen=True)
class PromptSpec:
    """Todo texto configurable que el coordinador agrega a la conversación.

    El hash cubre la versión del formato y los cuatro textos que afectan al modelo.
    `nombre` es una etiqueta humana y no modifica la identidad del contenido.
    """

    version: int
    nombre: str
    system_prompt: str
    mensaje_inicial: str
    formato_observacion: str
    mensaje_json_invalido: str

    def __post_init__(self):
        if type(self.version) is not int or self.version <= 0:
            raise ValueError("version requiere un entero positivo")
        if not isinstance(self.nombre, str) or not re.fullmatch(r"[a-z0-9][a-z0-9._-]*", self.nombre):
            raise ValueError("nombre de prompt inválido")
        textos = (self.system_prompt, self.mensaje_inicial,
                  self.formato_observacion, self.mensaje_json_invalido)
        if any(not isinstance(texto, str) or not texto.strip() for texto in textos):
            raise ValueError("los textos del prompt no pueden estar vacíos")
        if _placeholders(self.mensaje_inicial) != {"paciente_id"}:
            raise ValueError("mensaje_inicial requiere únicamente {paciente_id}")
        if _placeholders(self.formato_observacion) != {"herramienta", "observacion"}:
            raise ValueError("formato_observacion requiere {herramienta} y {observacion}")

    def _contenido(self) -> dict:
        return {
            "version": self.version,
            "system_prompt": self.system_prompt,
            "mensaje_inicial": self.mensaje_inicial,
            "formato_observacion": self.formato_observacion,
            "mensaje_json_invalido": self.mensaje_json_invalido,
        }

    @property
    def sha256(self) -> str:
        contenido = json.dumps(
            self._contenido(), ensure_ascii=False, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
        return hashlib.sha256(contenido).hexdigest()

@classmethod
def desde_dict(cls, dato: dict) -> "PromptSpec":
    if not isinstance(dato, dict) or set(dato) != _CAMPOS:
        raise ValueError("configuración de prompt incompleta o con campos desconocidos")
    esperado = dato["sha256"]
    if not isinstance(esperado, str) or not re.fullmatch(r"[0-9a-f]{64}", esperado):
        raise ValueError("sha256 de prompt inválido")
    prompt = cls(**{k: dato[k] for k in _CAMPOS if k != "sha256"})
    if prompt.sha256 != esperado:
        raise ValueError("el contenido del prompt no coincide con su sha256")
    return prompt

@classmethod
def cargar(cls, ruta: Path) -> "PromptSpec":
    try:
        dato = json.loads(Path(ruta).read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        raise ValueError("no se pudo leer una configuración de prompt válida") from None
    return cls.desde_dict(dato)

def tokenizar_conversacion(registro, tokenizer, max_seq_length):
    """Incluye respuesta y cierre del turno; excluye encabezados y todo contexto.

    Solo acepta plantillas/tokenizadores que preserven exactamente sus prefijos.
    No pide máscaras nativas (Gemma fijado no tiene bloques generation).
    """
    validar_registro(registro)
    if type(max_seq_length) is not int or max_seq_length <= 0:
        raise ValueError("max_seq_length requiere entero positivo")
    mensajes = registro["messages"]

    def tokens(historia, generar=False):
        salida = tokenizer.apply_chat_template(
            historia, tokenize=True, add_generation_prompt=generar,
            enable_thinking=False, padding=False, truncation=False, return_dict=True)
        ids = salida["input_ids"]
        if not isinstance(ids, list) or not ids or any(type(x) is not int or x < 0 for x in ids):
            raise ValueError("tokenizador devolvió IDs inválidos o anidados")
        if salida.get("attention_mask", [1] * len(ids)) != [1] * len(ids):
            raise ValueError("tokenización individual no debe contener padding")
        return ids

    ids = tokens(mensajes)
    if len(ids) > max_seq_length:
        raise ValueError("conversación excede max_seq_length; no se recorta")
    labels = [-100] * len(ids)
    for i, mensaje in enumerate(mensajes):
        if mensaje["role"] != "assistant":
            continue
        inicio = tokens(mensajes[:i], True)
        fin = tokens(mensajes[:i + 1])
        if ids[:len(inicio)] != inicio or ids[:len(fin)] != fin or len(fin) <= len(inicio):
            raise ValueError("plantilla/tokenizador no preserva prefijos; máscara insegura")
        labels[len(inicio):len(fin)] = ids[len(inicio):len(fin)]
    if all(x == -100 for x in labels):
        raise ValueError("conversación sin tokens supervisados")
    return {"input_ids": ids, "attention_mask": [1] * len(ids), "labels": labels}

